<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
class ExamSubject extends Model { protected $fillable=['exam_id','subject_id','max_marks','marks_status','submitted_at','reviewed_at','reviewed_by','review_note']; protected function casts(): array { return ['max_marks'=>'decimal:2','submitted_at'=>'datetime','reviewed_at'=>'datetime']; } protected static function booted():void { static::created(function(ExamSubject $examSubject):void { $examSubject->createDefaultComponents(); }); } public function createDefaultComponents():void { if($this->components()->exists())return; foreach([['Assignment 1',10,10],['Assignment 2',10,10],['Quiz/Test',10,10],['Mid-Term',20,20],['Final Exam',50,50]] as $index=>[$name,$maxMarks,$weight])$this->components()->create(['name'=>$name,'max_marks'=>$maxMarks,'weight'=>$weight,'sort_order'=>$index+1]); } public function exam(): BelongsTo { return $this->belongsTo(Exam::class); } public function subject(): BelongsTo { return $this->belongsTo(Subject::class); } public function marks(): HasMany { return $this->hasMany(ExamMark::class); } public function components(): HasMany { return $this->hasMany(ExamAssessmentComponent::class)->orderBy('sort_order'); } public function reviewer(): BelongsTo { return $this->belongsTo(User::class,'reviewed_by'); } }
